NAME = 'Est: Estonian Bible'
BOOK = 'I John'

CHAPTERS = {
    1: {
        1: 'Mis algusest oli, mis me oleme kuulnud, mis me oma silmaga oleme näinud, mida me oleme vaadelnud ja mida meie käed on katsunud, seda me räägime elu Sõnast',
        2: '- ja elu ilmus, ja me oleme näinud ja tunnistame ja kuulutame teile seda igavest elu, mis oli Isa juures ja ilmus meile -',
        3: 'mida me oleme näinud ja kuulnud, seda me kuulutame teile, et teilgi oleks osadus meiega. Ja meie osadus on Isaga ja Tema Pojaga, Jeesuse Kristusega.',
        4: 'Ja seda me kirjutame teile, et meie rõõm oleks täielik.',
        5: 'Ja see on kuulutus, mille me oleme kuulnud Temalt ja kuulutame teile, et Jumal on valgus ja Temas ei ole mingit pimedust.',
        6: 'Kui me ütleme, et meil on osadus Temaga, aga käime pimeduses, siis me valetame ega tee tõtt.',
        7: 'Aga kui me käime valguses, nõnda nagu Tema on valguses, siis on meil osadus üksteisega, ja Jeesuse Kristuse, Tema Poja Veri puhastab meid kõigest patust.',
        8: 'Kui me ütleme, et meil ei ole pattu, siis me petame iseendid ja tõde ei ole meie sees.',
        9: 'Kui me oma patud tunnistame, on Tema ustav ja õige, nii et Ta meile annab patud andeks ja puhastab meid kõigest ülekohtust.',
        10: 'Kui me ütleme, et me pole pattu teinud, siis me teeme Tema valelikuks ja Tema sõna ei ole meie sees.',
    },
    2: {
        1: 'Minu lapsukesed, seda ma kirjutan teile, et te ei teeks pattu. Ja kui keegi pattu teeb, siis on meil eestkostja Isa juures, Jeesus Kristus, Kes on õige.',
        2: 'Ja Tema on lepitus meie pattude eest; aga mitte ükspäinis meie, vaid ka kogu maailma pattude eest.',
        3: 'Ja sellest me tunneme, et me oleme Tema ära tundnud, et me peame Tema käske.',
        4: 'Kes ütleb: "Mina tunnen Teda", ega pea Tema käske, see on valelik ja tõde ei ole tema sees.',
        5: 'Aga kes peab Tema sõna, selles on tõesti Jumala armastus saanud täiuslikuks. Sellest me tunneme, et me oleme Tema sees.',
        6: 'Kes ütleb enese Tema sisse jäävat, see on ka kohustatud elama niisugust elu nagu Tema elas.',
        7: 'Armsad, ma ei kirjuta teile uut käsku, vaid vana käsku, mis teil on olnud algusest; see vana käsk on sõna, mida te olete kuulnud.',
        8: 'Taas ma kirjutan teile uue käsu, mis on tõsi Tema sees ja teie sees, sest pimedus möödub ja tõeline valgus juba paistab.',
        9: 'Kes ütleb enese valguses olevat, aga vihkab oma venda, see on pimeduses siitsaadik.',
        10: 'Kes oma venda armastab, see püsib valguses ja temas ei ole pahandust.',
        11: 'Aga kes oma venda vihkab, see on pimeduses ja käib pimeduses ega tea, kuhu ta läheb, sest pimedus on teinud ta silmad pimedaks.',
        12: 'Ma kirjutan teile, lapsukesed, sest teie patud on andeks antud Tema nime pärast.',
        13: 'Ma kirjutan teile, isad, sest te olete ära tundnud Tema, Kes on algusest. Ma kirjutan teile, noored mehed, sest te olete ära võitnud tigeda.',
        14: 'Ma olen kirjutanud teile, lapsukesed, sest te olete ära tundnud Isa. Ma olen kirjutanud teile, isad, sest te olete ära tundnud Tema, Kes on algusest. Ma olen kirjutanud teile, noored mehed, sest te olete tugevad ja Jumala sõna püsib teie sees ja et te olete ära võitnud tigeda.',
        15: 'Ärge armastage maailma ega seda, mis on maailmas. Kui keegi maailma armastab, siis ei ole Isa armastust tema sees.',
        16: 'Sest kõik, mis on maailmas, lihahimu, silmahimu ja elukõrkus, ei ole Isast, vaid on maailmast.',
        17: 'Ja maailm kaob ja tema himu; aga kes teeb Jumala tahtmist, püsib igavesti.',
        18: 'Lapsukesed, nüüd on viimne aeg! Ja nagu te olete kuulnud, et kristusevastane tuleb, nõnda ongi nüüd ilmunud palju kristusevastaseid; siit me tunneme, et käes on viimne aeg.',
        19: 'Meist nad on lähtunud, kuid nad ei olnud meist; sest kui nad oleksid olnud meist, siis nad oleksid jäänud meie juurde. Ent nad läksid ära, et saaks ilmsiks, et kõik ei ole meist.',
        20: 'Teil on võidmine Pühalt ja teil kõigil on teadmine.',
        21: 'Mina ei ole teile kirjutanud sellepärast et te ei tea tõde, vaid et te seda teate ja et ühtki valet ei tule tõe seest.',
        22: 'Kes on valelik kui mitte see, kes salgab, et Jeesus on Kristus? See on kristusevastane, kes salgab Isa ja Poega.',
        23: 'Igaüks, kes salgab Poja, sel ei ole ka Isa. Kes tunnistab Poega, sellel on ka Isa.',
        24: 'Mida te olete algusest saadik kuulnud, see püsigu teis. Kui teis püsib see, mida te algusest saadik olete kuulnud, siis teiegi püsite Pojas ja Isas.',
        25: 'Ja see on tõotus, mille Tema meile on tõotanud: igavene elu.',
        26: 'Seda ma olen teile kirjutanud neist, kes teid eksitavad.',
        27: 'Ja teie - see võidmine, mille te olete saanud Temalt, jääb ju teisse ja teil ei ole vajadust, et keegi teid õpetaks; vaid nagu Tema võidmine teid kõiges õpetab, nõnda on see tõsi ega ole vale; ja nõnda nagu see teid on õpetanud, nõnda püsige Temas.',
        28: 'Ja nüüd, lapsukesed, jääge Temasse, et kui Ta ilmub, meil oleks julgus ja mitte häbi Tema ees, kui ta tuleb.',
        29: 'Kui te teate, et Ta on õige, siis te mõistate, et igaüks, kes teeb õigust, on Temast sündinud.',
    },
    3: {
        1: 'Vaadake, missuguse armastuse Isa on meile andnud, et meid hüütakse Jumala lasteks! Ja seda me olemegi. Sellepärast maailm ei tunne meid, sest ta ei tunne Teda.',
        2: 'Armsad, me oleme nüüd Jumala lapsed ega ole veel saanud avalikuks, mis me tulevikus oleme; aga me teame, et me Tema ilmudes oleme Tema sarnased, sest me näeme siis Teda nagu Tema on.',
        3: 'Ja igaüks, kellel on niisugune lootus Tema peale, puhastab ennast, nõnda nagu Temagi on puhas.',
        4: 'Igaüks, kes pattu teeb, teeb ka seda, mis on käsu vastu; ja patt on see, mis on käsu vastu.',
        5: 'Ja te teate, et Tema on ilmunud patte ära võtma; ja Temas ei ole pattu.',
        6: 'Ükski, kes jääb Tema sisse, ei tee pattu; ükski, kes pattu teeb, ei ole teda näinud ega Teda tundnud.',
        7: 'Lapsukesed, ärgu ükski teid eksitagu! Kes teeb õigust, see on õige, nõnda nagu Temagi on õige.',
        8: 'Kes pattu teeb, see on kuradist; sest kurat teeb pattu algusest saadik. Selleks on Jumala Poeg ilmunud, et Ta tühistaks kuradi teod.',
        9: 'Ükski, kes on Jumalast sündinud, ei tee pattu, sest tema seeme püsib Temas ja ta ei või pattu teha, sellepärast et ta on Jumalast sündinud.',
        10: 'Sellest ilmneb, kummad on Jumala lapsed ja kummad kuradi lapsed. Ükski, kes ei tee õigust, ei ole Jumalast, ega see, kes ei armasta oma venda.',
        11: 'Sest see on sõnum, mida te algusest saadik olete kuulnud, et me peame üksteist armastama;',
        12: 'mitte nõnda, nagu Kain, kes oli tigedast ja tappis oma venna. Ja mispärast ta tappis tema? Sellepärast et tema teod olid kurjad ja tema venna teod õiged.',
        13: 'Ärge pange imeks, vennad, kui maailm teid vihkab!',
        14: 'Me teame, et oleme tulnud surmast elusse, sest me armastame vendi; kes venda ei armasta, see jääb surmasse.',
        15: 'Igaüks, kes vihkab oma venda, on inimesetapja; ja te teate, et ühelgi inimesetapjal ei ole igavest elu, mis temasse jääks.',
        16: 'Sellest me oleme ära tundnud Jumala armastuse, et Tema Oma elu on jätnud meie eest; ja meiegi peame jätma elu vendade eest.',
        17: 'Kui nüüd kellelgi on selle maailma vara ja ta näeb oma venna puuduses olevat ja suleb oma südame tema eest, kuidas saab Jumala armastus jääda temasse?',
        18: 'Lapsukesed, ärgem armastagem sõnaga ega keelega, vaid teoga ja tõega!',
        19: 'Sellest me tunneme, et oleme tõe seest ja võime vaigistada tema ees oma südant,',
        20: 'et kui meie süda meid hukka mõistab, Jumal on suurem kui meie süda ja teab kõik.',
        21: 'Armsad, kui meie süda meid hukka ei mõista, on meil julgus Jumala ees,',
        22: 'ja mida me iganes palume, seda me saame Temalt, sest me peame Tema käske ja teeme, mis on Temale meelepärast.',
        23: 'Ja see on Tema käsk, et me peame uskuma Tema Poja Jeesuse Kristuse nimesse ja armastama üksteist, nagu Tema meile on käsu andnud.',
        24: 'Ja kes peab Tema käske, see jääb Temasse ja Tema sellesse. Ja sellest me tunneme, et Tema jääb meisse, sellest Vaimust, Kelle Ta meile on andnud.',
    },
    4: {
        1: 'Armsad, ärge uskuge igat vaimu, vaid katsuge vaimud läbi, kas nad on Jumalast; sest palju valeprohveteid on välja läinud maailma.',
        2: 'Sellest te tunnetate Jumala Vaimu: iga vaim, kes tunnistab Jeesust Kristust lihas tulnud olevat, see on Jumalast.',
        3: 'Ja ükski vaim, kes ei tunnista seda Jeesust, ei ole Jumalast; ja see on kristusevastase vaim, kelle te olete kuulnud tulemas olevat ja nüüd juba on maailmas.',
        4: 'Teie, lapsukesed, olete Jumalast ja olete nad ära võitnud; sest suurem on See, Kes on teie sees, kui see, kes on maailmas.',
        5: 'Nemad on maailmast; sellepärast nad räägivad maailmast ja maailm kuuleb neid.',
        6: 'Meie oleme Jumalast; kes tunneb Jumalat, võtab meid kuulda; kes ei ole Jumalast, ei võta meid kuulda. Sellest me tunneme tõe Vaimu ja eksituse vaimu.',
        7: 'Armsad, armastagem üksteist, sest armastus on Jumalast, ja igaüks, kes armastab, on Jumalast sündinud ja tunneb Jumalat.',
        8: 'Kes ei armasta, ei ole Jumalat ära tundnud; sest Jumal on armastus.',
        9: 'Selles on Jumala armastus meie vastu avalikuks saanud, et Jumal Oma ainusündinud Poja on läkitanud maailma, et me Tema läbi elaksime.',
        10: 'Selles on armastus - ei mitte selles, et meie oleme armastanud Jumalat, vaid selles, et Tema meid on armastanud ja on läkitanud Oma Poja lepituseks meie pattude eest.',
        11: 'Armsad, kui Jumal meid nõnda on armastanud, siis peame ka meie üksteist armastama.',
        12: 'Jumalat ei ole iialgi ükski näinud. Kui me üksteist armastame, siis jääb Jumal meisse ja Tema armastus on saanud täiuslikuks meie sees.',
        13: 'Sellest, et Ta meile on andnud osa Oma Vaimust, me tunneme, et me jääme Temasse ja Tema meisse.',
        14: 'Ja me oleme näinud ja tunnistame, et Isa on läkitanud Poja maailma Õnnistegijaks.',
        15: 'Kes tunnistab, et Jeesus on Jumala Poeg, sellesse jääb Jumal ning tema Jumalasse.',
        16: 'Ja me oleme tundma õppinud ja uskunud armastust, mis Jumalal on meie vastu. Jumal on armastus, ja kes jääb armastusse, see jääb Jumalasse ning Jumal jääb temasse.',
        17: 'Selles on armastus saanud täiuslikuks meie sees, et meil oleks julgust kohtupäeval; sest otsekui Tema on, nõnda oleme ka meie selles maailmas.',
        18: 'Kartust ei ole armastuses, vaid täiuslik armastus ajab kartuse välja, sest kartuses on nuhtlust; aga kes kardab, ei ole saanud täiuslikuks armastuses.',
        19: 'Me armastame, sest Tema on meid enne armastanud.',
        20: 'Kui keegi ütleb: "Mina armastan Jumalat", ja vihkab oma venda, siis ta on valelik. Sest kes ei armasta oma venda, keda ta on näinud, ei või armastada Jumalat, Keda ta ei ole näinud.',
        21: 'Ja meil on Temalt see käsk, et kes armastab Jumalat, see armastab ka oma venda.',
    },
    5: {
        1: 'Igaüks, kes usub, et Jeesus on Kristus, on Jumalast sündinud; ja igaüks, kes armastab Teda, Kes Tema on sünnitanud, see armastab ka Temast sündinut.',
        2: 'Sellest me tunneme, et me armastame Jumala lapsi, kui armastame Jumalat ja täidame Tema käske.',
        3: 'Sest see on Jumala armastus, et me peame Tema käske, ja Tema käsud ei ole rasked!',
        4: 'Sest kõik, mis Jumalast on sündinud, võidab maailma ära; ja see ongi see võit, mis on ära võitnud maailma: meie usk!',
        5: 'Kes on, kes võidab maailma, kui aga see, kes usub, et Jeesus on Jumala Poeg?',
        6: 'Tema on See, Kes tuleb vee ja vere kaudu, Jeesus Kristus, mitte veega üksi, vaid vee ja verega. Ja Vaim on, Kes tunnistab, et Vaim on tõde.',
        7: 'Sest kolm on, Kes tunnistavad:',
        8: 'Vaim ja vesi ja veri, ja need kolm liituvad ühte.',
        9: 'Kui me võtame vastu inimeste tunnistuse, siis on Jumala tunnistus suurem, sest see on Jumala tunnistus, mis Ta on tunnistanud Oma Pojast.',
        10: 'Kes usub Jumala Pojasse, sellel on tunnistus enese sees. Kes ei usu Jumalat, on teinud tema valelikuks, sest ta pole uskunud tunnistust, mis Jumal on tunnistanud Oma Pojast.',
        11: 'Ja see on see tunnistus, et Jumal on meile andnud igavese elu ja see elu on Tema Pojas.',
        12: 'Kellel on Poeg, sellel on elu; kellel Jumala Poega ei ole, sellel ei ole elu.',
        13: 'Seda ma olen teile kirjutanud, et te teaksite enestel olevat igavese elu, teil, kes usute Jumala Poja nimesse.',
        14: 'Ja see on see julge avameelsus, mis meil on Tema ees, et kui me midagi palume Tema tahtmist mööda, Ta kuuleb meid.',
        15: 'Ja kui me teame, et Ta meid kuuleb kõiges, mida me palume, siis me ka teame, et meil on käes need palved, mis me Temalt oleme palunud.',
        16: 'Kui keegi näeb oma venda pattu tegevat, pattu, mis ei ole surmaks, siis ta tehku palvet, ja Jumal annab temale elu, neile nimelt, kes ei tee pattu surmaks. On patt, mis on surmaks; selle kohta ma ei ütle, et tuleks paluda.',
        17: 'Kõik ülekohus on patt; ja on pattu, mis ei ole surmaks.',
        18: 'Me teame, et ükski Jumalast sündinu ei tee pattu, vaid Jumalast Sündinu hoiab teda, ja tige ei puutu temasse.',
        19: 'Me teame, et oleme Jumalast ja kõik maailm on tigeda võimuses.',
        20: 'Aga me teame, et Jumala Poeg on tulnud ja andnud meile mõistuse, et me tunnetaksime Tõelise ja oleksime Tõelises, Tema Pojas Jeesuses Kristuses. Seesama on tõeline Jumal ja igavene elu.',
        21: 'Lapsukesed, hoiduge ebajumalaist!',
    },
}
